window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d96cd691df48221"]={"versions": [{"id": "FIG-5d96cd691df48221", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt ein Bit-/Byte-Layout eines Protokoll-Headers (PDU-Format) im AUTOSAR Classic FlexRay Transport Layer (FlexRay TP) dar. Es definiert die Feldanordnung und Struktur des optionalen 2-Byte-Adress-Headers, der bei erweiterter bzw. gerouteter Adressierung den Nutzdaten vorangestellt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Der Adress-Header besteht aus zwei sequenziellen Feldern:</p>\n<ul class=\"fig-list\">\n<li><strong>Target Address (16 Bit)</strong>: 2 Bytes lange logische Zieladresse des Empfängers bzw. der Ziel-ECU.</li>\n<li><strong>Source Address (16 Bit)</strong>: 2 Bytes lange logische Quelladresse des Senders bzw. der Ursprungs-ECU.</li>\n</ul>\n<p class=\"fig-p\">Die Gesamtlänge des Adress-Headers beträgt exakt 4 Bytes (32 Bit). Schnittstellenseitig liegt dieser Header innerhalb der N-PDU des FlexRay TP oberhalb bzw. vor dem eigentlichen TP-Payload / PCI.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Datenstruktur. Bei der PDU-Serialisierung durch den Sender werden zuerst die 2 Bytes der Zieladresse (<code>Target Address</code>) und unmittelbar danach die 2 Bytes der Quelladresse (<code>Source Address</code>) in den Datenstrom eingefügt (Big-Endian / Network Byte Order). Der empfangende FlexRay-TP-Stack parst diese 4 Bytes aus der eingehenden N-PDU, verifiziert die <code>Target Address</code> anhand lokaler Adressfilter und identifiziert über die <code>Source Address</code> den sendenden Kommunikationspartner.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Feldbreiten und -abfolge für das 2-Byte-Adressierungsformat im FlexRay TP. Entwickler von Kommunikations-Stacks und Generatoren müssen sicherstellen, dass bei aktivierter 2-Byte-Adressierung exakt 4 Bytes Header vorangestellt werden. Dies reduziert die maximal verfügbare Nutzlast (Payload) der FlexRay-Frames entsprechend um 4 Bytes und muss beim Segmentierungs- und Reassembly-Algorithmus berücksichtigt werden.</p>"}, {"id": "FIG-ca3831b63858ed4f", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt ein Bit-/Byte-Layout eines Protokoll-Headers (PDU-Format) im AUTOSAR Classic FlexRay Transport Layer (FlexRay TP) dar. Es definiert die Feldanordnung und Struktur des optionalen 2-Byte-Adress-Headers, der bei erweiterter bzw. gerouteter Adressierung den Nutzdaten vorangestellt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Der Adress-Header besteht aus zwei sequenziellen Feldern:</p>\n<ul class=\"fig-list\">\n<li><strong>Target Address (16 Bit)</strong>: 2 Bytes lange logische Zieladresse des Empfängers bzw. der Ziel-ECU.</li>\n<li><strong>Source Address (16 Bit)</strong>: 2 Bytes lange logische Quelladresse des Senders bzw. der Ursprungs-ECU.</li>\n</ul>\n<p class=\"fig-p\">Die Gesamtlänge des Adress-Headers beträgt exakt 4 Bytes (32 Bit). Schnittstellenseitig liegt dieser Header innerhalb der N-PDU des FlexRay TP oberhalb bzw. vor dem eigentlichen TP-Payload / PCI.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Datenstruktur. Bei der PDU-Serialisierung durch den Sender werden zuerst die 2 Bytes der Zieladresse (<code>Target Address</code>) und unmittelbar danach die 2 Bytes der Quelladresse (<code>Source Address</code>) in den Datenstrom eingefügt (Big-Endian / Network Byte Order). Der empfangende FlexRay-TP-Stack parst diese 4 Bytes aus der eingehenden N-PDU, verifiziert die <code>Target Address</code> anhand lokaler Adressfilter und identifiziert über die <code>Source Address</code> den sendenden Kommunikationspartner.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Feldbreiten und -abfolge für das 2-Byte-Adressierungsformat im FlexRay TP. Entwickler von Kommunikations-Stacks und Generatoren müssen sicherstellen, dass bei aktivierter 2-Byte-Adressierung exakt 4 Bytes Header vorangestellt werden. Dies reduziert die maximal verfügbare Nutzlast (Payload) der FlexRay-Frames entsprechend um 4 Bytes und muss beim Segmentierungs- und Reassembly-Algorithmus berücksichtigt werden.</p>"}], "trans": [{"from": "FIG-5d96cd691df48221", "to": "FIG-ca3831b63858ed4f", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
